import os
import time

def make_dir(directory):
    if not os.path.isdir(directory):
        try:
            os.makedirs(directory)
        except OSError as error:
            raise OSError('Unable to create directory ' + directory) from error

def get_timestamp():
    timestamp = time.strftime('%Y%m%d%H%M%S')
    return timestamp

