class SmartLocRaw(NavData):

    def __init__(self, input_path):
        super().__init__(csv_path=input_path, sep=';')

    def postprocess(self):
        self['gnss_id'] = np.array([x.lower() for x in self['gnss_id']], dtype=object)
        self['gps_millis'] = [tow_to_gps_millis(*x) for x in zip(self['gps_week'], self['gps_tow'])]
        self['heading_rx_gt_rad'] = np.pi / 2.0 - self['heading_rx_gt_rad']
        self['heading_rx_gt_rad'] = wrap_0_to_2pi(self['heading_rx_gt_rad'])
        self.remove(rows=['GPSWeek [weeks]', 'GPSSecondsOfWeek [s]'], inplace=True)
        nlos_idx = 'NLOS (0 == no, 1 == yes, # == No Information)'
        nlos_new = 'NLOS (0 == no, 1 == yes, 2 == No Information)'
        if self.is_str(nlos_idx) and '#' in np.unique(self[nlos_idx]):
            self[nlos_idx] = np.where(self[nlos_idx] == '#', '2', self[nlos_idx]).astype(int)
        self.rename({nlos_idx: nlos_new}, inplace=True)

    @staticmethod
    def _row_map():
        row_map = {'GPS week number (week) [weeks]': 'gps_week', 'Measurement time of week (rcvTow) [s]': 'gps_tow', 'Pseudorange measurement (prMes) [m]': 'raw_pr_m', 'GNSS identifier (gnssId) []': 'gnss_id', 'Satellite identifier (svId) []': 'sv_id', 'Carrier-to-noise density ratio (cno) [dbHz]': 'cn0_dbhz', 'Estimated pseudorange measurement standard deviation (prStdev) [m]': 'raw_pr_sigma_m', 'Doppler measurement (doMes) [Hz]': 'doppler_hz', 'Estimated Doppler measurement standard deviation (doStdev) [Hz]': 'doppler_sigma_hz', 'Longitude (GT Lon) [deg]': 'lon_rx_gt_deg', 'Longitude Cov (GT Lon) [deg]': 'lon_sigma_rx_gt_deg', 'Latitude (GT Lat) [deg]': 'lat_rx_gt_deg', 'Latitude Cov (GT Lat) [deg]': 'lat_sigma_rx_gt_deg', 'Height above ellipsoid (GT Height) [m]': 'alt_rx_gt_m', 'Height above ellipsoid Cov (GT Height) [m]': 'alt_sigma_rx_gt_m', 'Heading (0° = East, counterclockwise) - (GT Heading) [rad]': 'heading_rx_gt_rad', 'Velocity (GT Velocity) [m/s]': 'v_rx_gt_mps', 'Acceleration (GT Acceleration) [ms^2]': 'a_rx_gt_mps2'}
