import os
import datetime
import pynmea2
import numpy as np
import pandas as pd
from pynmea2.nmea_utils import timestamp, datestamp
from gnss_lib_py.parsers.navdata import NavData
from gnss_lib_py.utils.coordinates import geodetic_to_ecef
from gnss_lib_py.utils.time_conversions import datetime_to_gps_millis

class Nmea(NavData):

    def __init__(self, filename, msg_types=None, check=False, keep_raw=False, include_ecef=False):
        if msg_types is None:
            msg_types = ['GGA', 'RMC']
        pd_df = pd.DataFrame()
        field_dict = {}
        prev_timestamp = None
        if not isinstance(filename, (str, os.PathLike)):
            raise TypeError('filename must be string or path-like')
        if not os.path.exists(filename):
            raise FileNotFoundError('file not found')
        with open(filename, 'r', encoding='UTF-8') as open_file:
            for line in open_file:
                check_ind = line.find('*')
                if not check and '*' in line:
                    check_ind = line.find('*')
                    line = line[:check_ind]
                try:
                    msg = pynmea2.parse(line, check=check)
                    if 'timestamp' in list(msg.name_to_idx.keys()):
                        if prev_timestamp is None:
                            prev_timestamp = msg.timestamp
                        elif msg.timestamp != prev_timestamp:
                            time = field_dict.pop('timestamp')
                            date = field_dict.pop('datestamp')
                            delta_t = datetime.datetime.combine(datestamp(date), timestamp(time))
                            field_dict['gps_millis'] = datetime_to_gps_millis(delta_t)
                            new_row = pd.DataFrame([field_dict])
                            pd_df = pd.concat([pd_df, new_row])
                            field_dict = {}
                            prev_timestamp = msg.timestamp
                    if msg.sentence_type in msg_types:
                        field_dict['lat_float'] = msg.latitude
                        field_dict['lon_float'] = msg.longitude
                        if keep_raw:
                            ignore = []
                        else:
                            ignore = ['lat', 'lat_dir', 'lon', 'lon_dir']
                        ignore += ['mag_variation', 'mag_var_dir', 'mode_indicator', 'nav_status']
                        for field in msg.name_to_idx:
                            if field not in ignore:
                                field_dict[field] = msg.data[msg.name_to_idx[field]]
                except pynmea2.ChecksumError as check_err:
                    raise Exception('Cannot skip any messages. Need both' + ' GGA and RMC messages for ' + 'all of date, time, and all of LLH') from check_err
            time = field_dict.pop('timestamp')
            date = field_dict.pop('datestamp')
            delta_t = datetime.datetime.combine(datestamp(date), timestamp(time))
            field_dict['gps_millis'] = datetime_to_gps_millis(delta_t)
            new_row = pd.DataFrame([field_dict])
            pd_df = pd.concat([pd_df, new_row])
        pd_df['true_course_rad'] = np.pi / 180.0 * pd_df['true_course'].astype(float)
        pd_df['altitude'] = pd_df['altitude'].astype(float)
        super().__init__(pandas_df=pd_df)
        if include_ecef:
            self.include_ecef()

    @staticmethod
    def _row_map():
        row_map = {'lat_float': 'lat_rx_deg', 'lon_float': 'lon_rx_deg', 'altitude': 'alt_rx_m', 'spd_over_grnd': 'vx_rx_mps', 'true_course': 'heading_raw_rx_deg', 'true_course_rad': 'heading_rx_rad'}
        return row_map

    def include_ecef(self):
        ecef = geodetic_to_ecef(self[['lat_rx_deg', 'lon_rx_deg', 'alt_rx_m']])
        self['x_rx_m'] = ecef[0, :]
        self['y_rx_m'] = ecef[1, :]
        self['z_rx_m'] = ecef[2, :]

