import os
import pathlib
from math import floor
from multiprocessing import Process
import numpy as np
import pandas as pd
from cycler import cycler
import plotly.express as px
import plotly.graph_objects as go
import matplotlib as mpl
import matplotlib.pyplot as plt
from matplotlib.collections import LineCollection
from matplotlib.colors import to_rgb, ListedColormap
import gnss_lib_py.utils.file_operations as fo
from gnss_lib_py.parsers.navdata import NavData
from gnss_lib_py.utils.coordinates import add_el_az
STANFORD_COLORS = ['#8C1515', '#6FC3FF', '#006F54', '#620059', '#E98300', '#FEDD5C', '#E04F39', '#4298B5', '#8F993E', '#651C32', '#B1040E', '#016895', '#279989']
MARKERS = ['o', '*', 'P', 'v', 's', '^', 'p', '<', 'h', '>', 'H', 'X', 'D']
GNSS_ORDER = ['gps', 'glonass', 'galileo', 'beidou', 'qzss', 'irnss', 'sbas', 'unknown']
mpl.rcParams['axes.prop_cycle'] = cycler(color=STANFORD_COLORS) + cycler(marker=MARKERS)
TIMESTAMP = fo.get_timestamp()

def plot_metric(navdata, *args, groupby=None, title=None, save=False, prefix='', fname=None, markeredgecolor='k', markeredgewidth=0.2, **kwargs):
    x_metric, y_metric = _parse_metric_args(navdata, *args)
    if groupby is not None:
        navdata.in_rows(groupby)
    if not isinstance(prefix, str):
        raise TypeError('Prefix must be a string.')
    fig, axes = _get_new_fig()
    if x_metric is None:
        x_data = None
        xlabel = 'INDEX'
        if title is None:
            title = _get_label({y_metric: y_metric})
    else:
        if title is None:
            title = _get_label({x_metric: x_metric}) + ' vs. ' + _get_label({y_metric: y_metric})
        xlabel = _get_label({x_metric: x_metric})
    if groupby is not None:
        all_groups = np.unique(navdata[groupby])
        if groupby == 'gnss_id':
            all_groups = _sort_gnss_ids(all_groups)
        for group in all_groups:
            subset = navdata.where(groupby, group)
            y_data = np.atleast_1d(subset[y_metric])
            if x_metric is None:
                x_data = range(len(y_data))
            else:
                x_data = np.atleast_1d(subset[x_metric])
            axes.plot(x_data, y_data, label=_get_label({groupby: group}), markeredgecolor=markeredgecolor, markeredgewidth=markeredgewidth, **kwargs)
    else:
        y_data = np.atleast_1d(navdata[y_metric])
        if x_metric is None:
            x_data = range(len(y_data))
        else:
            x_data = np.atleast_1d(navdata[x_metric])
        axes.plot(x_data, y_data, markeredgecolor=markeredgecolor, markeredgewidth=markeredgewidth, **kwargs)
    handles, _ = axes.get_legend_handles_labels()
    if len(handles) > 0:
        plt.legend(loc='upper left', bbox_to_anchor=(1.05, 1), title=_get_label({groupby: groupby}))
    plt.title(title)
    plt.xlabel(xlabel)
    plt.ylabel(_get_label({y_metric: y_metric}))
    fig.tight_layout()
    if save:
        _save_figure(fig, title, prefix, fname)
    return fig

def plot_metric_by_constellation(navdata, *args, save=False, prefix='', fname=None, **kwargs):
    x_metric, y_metric = _parse_metric_args(navdata, *args)
    if not isinstance(prefix, str):
        raise TypeError('Prefix must be a string.')
    if 'gnss_id' not in navdata.rows:
        raise KeyError('gnss_id row missing,' + ' try using' + ' the plot_metric() function call instead')
    figs = []
    for constellation in _sort_gnss_ids(np.unique(navdata['gnss_id'])):
        const_subset = navdata.where('gnss_id', constellation)
        if 'signal_type' in const_subset.rows:
            for signal in np.unique(const_subset['signal_type']):
                title = _get_label({'gnss_id': constellation, 'signal_type': signal})
                signal_subset = navdata.where('signal_type', signal)
                if 'sv_id' in signal_subset.rows:
                    fig = plot_metric(signal_subset, x_metric, y_metric, groupby='sv_id', title=title, save=save, prefix=prefix, fname=fname, **kwargs)
                    figs.append(fig)
                else:
                    fig = plot_metric(signal_subset, x_metric, y_metric, title=title, save=save, prefix=prefix, fname=fname, **kwargs)
                    figs.append(fig)
        else:
            title = _get_label({'gnss_id': constellation})
            if 'sv_id' in const_subset.rows:
                fig = plot_metric(const_subset, x_metric, y_metric, groupby='sv_id', title=title, save=save, prefix=prefix, fname=fname, **kwargs)
                figs.append(fig)
            else:
                fig = plot_metric(const_subset, x_metric, y_metric, title=title, save=save, prefix=prefix, fname=fname, **kwargs)
                figs.append(fig)
    return figs

def plot_skyplot(navdata, receiver_state, save=False, prefix='', fname=None, add_sv_id_label=True):
    if not isinstance(prefix, str):
        raise TypeError('Prefix must be a string.')
    if 'el_sv_deg' not in navdata.rows or 'az_sv_deg' not in navdata.rows:
        add_el_az(navdata, receiver_state, inplace=True)
    fig = plt.figure(figsize=(6, 4.5))
    axes = fig.add_subplot(111, projection='polar')
    navdata = navdata.copy()
    navdata['az_sv_rad'] = np.radians(navdata['az_sv_deg'])
    for c_idx, constellation in enumerate(_sort_gnss_ids(np.unique(navdata['gnss_id']))):
        const_subset = navdata.where('gnss_id', constellation)
        color = 'C' + str(c_idx % len(STANFORD_COLORS))
        cmap = _new_cmap(to_rgb(color))
        marker = MARKERS[c_idx % len(MARKERS)]
        const_label_created = False
        for sv_name in np.unique(const_subset['sv_id']):
            sv_subset = const_subset.where('sv_id', sv_name)
            sv_subset = sv_subset.where('az_sv_rad', np.nan, 'neq')
            sv_subset = sv_subset.where('el_sv_deg', np.nan, 'neq')
            if len(sv_subset) == 0:
                continue
            step = max(1, int(len(sv_subset) / 50.0))
            points = np.array([np.atleast_1d(sv_subset['az_sv_rad'])[::step], np.atleast_1d(sv_subset['el_sv_deg'])[::step]]).T
            points = np.reshape(points, (-1, 1, 2))
            segments = np.concatenate([points[:-1], points[1:]], axis=1)
            norm = plt.Normalize(0, len(segments))
            local_coord = LineCollection(segments, cmap=cmap, norm=norm, linewidths=(4,), array=range(len(segments)))
            axes.add_collection(local_coord)
            if not const_label_created:
                axes.plot(np.atleast_1d(sv_subset['az_sv_rad'])[-1], np.atleast_1d(sv_subset['el_sv_deg'])[-1], c=color, marker=marker, markersize=8, label=_get_label({'gnss_id': constellation}))
                const_label_created = True
            else:
                axes.plot(np.atleast_1d(sv_subset['az_sv_rad'])[-1], np.atleast_1d(sv_subset['el_sv_deg'])[-1], c=color, marker=marker, markersize=8)
            if add_sv_id_label:
                az_offset = 3.0 * np.radians(np.cos(np.atleast_1d(sv_subset['az_sv_rad'])[-1]))
                el_offset = -3.0 * np.sin(np.atleast_1d(sv_subset['az_sv_rad'])[-1])
                axes.text(np.atleast_1d(sv_subset['az_sv_rad'])[-1] + az_offset, np.atleast_1d(sv_subset['el_sv_deg'])[-1] + el_offset, str(int(sv_name)))
    axes.set_theta_zero_location('N')
    axes.set_theta_direction(-1)
    axes.set_yticks(range(0, 60 + 10, 30))
    axes.set_yticklabels(['', '$30\\degree$', '$60\\degree$'])
    axes.set_ylim(90, 0)
    handles, _ = axes.get_legend_handles_labels()
    if len(handles) > 0:
        axes.legend(loc='upper left', bbox_to_anchor=(1.05, 1), title=_get_label({'constellation': 'constellation'}))
    fig.tight_layout()
    if save:
        _save_figure(fig, 'skyplot', prefix=prefix, fnames=fname)
    return fig

def plot_map(*args, sections=0, save=False, prefix='', fname=None, width=730, height=520, **kwargs):
    figure_df = None
    color_discrete_map = {}
    for idx, traj_data in enumerate(args):
        if not isinstance(traj_data, NavData):
            raise TypeError('Input(s) to plot_map() must be of type ' + 'NavData.')
        traj_idxs = traj_data.find_wildcard_indexes(wildcards=['lat_*_deg', 'lon_*_deg'], max_allow=1, excludes=[['lat_sigma_*_deg'], ['lon_sigma_*_deg']])
        label_name = _get_label({'': '_'.join(traj_idxs['lat_*_deg'][0].split('_')[1:-1])})
        data = {'latitude': traj_data[traj_idxs['lat_*_deg'][0]], 'longitude': traj_data[traj_idxs['lon_*_deg'][0]], 'Trajectory': [label_name] * len(traj_data)}
        if sections >= 2:
            traj_data.in_rows('gps_millis')
            data['gps_millis'] = traj_data['gps_millis']
        traj_df = pd.DataFrame.from_dict(data)
        color_discrete_map[label_name] = STANFORD_COLORS[idx % len(STANFORD_COLORS)]
        if figure_df is None:
            figure_df = traj_df
        else:
            figure_df = pd.concat([figure_df, traj_df])
    zoom, center = _zoom_center(lats=figure_df['latitude'].to_numpy(), lons=figure_df['longitude'].to_numpy(), width_to_height=float(0.9 * width) / height)
    fig = px.scatter_mapbox(figure_df, lat='latitude', lon='longitude', color='Trajectory', color_discrete_map=color_discrete_map, zoom=zoom, center=center, width=width, height=height)
    fig.update_layout(mapbox_style='open-street-map')
    fig.update_layout(margin={'r': 0, 't': 0, 'l': 0, 'b': 0})
    fig.update_layout(**kwargs)
    if sections <= 1:
        if save:
            _save_plotly(fig, titles='map', prefix=prefix, fnames=fname, width=width, height=height)
        return fig
    figs = [fig]
    titles = ['map_full']
    time_groups = np.array_split(np.sort(figure_df['gps_millis'].unique()), sections)
    for time_idx, time_group in enumerate(time_groups):
        zoomed_df = figure_df[(figure_df['gps_millis'] >= min(time_group)) & (figure_df['gps_millis'] <= max(time_group))]
        zoom, center = _zoom_center(lats=zoomed_df['latitude'].to_numpy(), lons=zoomed_df['longitude'].to_numpy(), width_to_height=float(0.9 * width) / height)
        fig = px.scatter_mapbox(figure_df, lat='latitude', lon='longitude', color='Trajectory', color_discrete_map=color_discrete_map, zoom=zoom, center=center, width=width, height=height)
        fig.update_layout(mapbox_style='open-street-map')
        fig.update_layout(margin={'r': 0, 't': 0, 'l': 0, 'b': 0})
        fig.update_layout(**kwargs)
        figs.append(fig)
        titles.append('map_section_' + str(time_idx + 1))
    if save:
        _save_plotly(figs, titles=titles, prefix=prefix, fnames=fname, width=width, height=height)
    return figs

def close_figures(figs=None):
    if figs is None:
        plt.close('all')
    elif isinstance(figs, plt.Figure):
        plt.close(figs)
    elif isinstance(figs, list):
        for fig in figs:
            if isinstance(fig, plt.Figure):
                plt.close(fig)
    else:
        raise TypeError('Must be either a single figure or list of figures.')

def _get_new_fig():
    fig = plt.figure()
    axes = plt.gca()
    axes.ticklabel_format(useOffset=False)
    fig.autofmt_xdate()
    return (fig, axes)

def _get_label(inputs):
    if not isinstance(inputs, dict):
        raise TypeError('_get_label input must be dictionary.')
    units = {'m', 'km', 'deg', 'rad', 'sec', 's', 'hr', 'min', 'mps', 'kmph', 'mph', 'dgps', 'radps', 'mps2'}
    unit_replacements = {'mps': 'm/s', 'kmph': 'km/hr', 'mph': 'miles/hr', 'degps': 'deg/s', 'radps': 'rad/s', 'mps2': 'm/s^2'}
    label = ''
    for key, value in inputs.items():
        if len(label) != 0:
            value = ' ' + value
        if not isinstance(value, str):
            value = str(value)
        try:
            value = str(int(float(value)))
        except ValueError:
            pass
        value = value.split('_')
        if value[-1] in units:
            if value[-1] in unit_replacements:
                value[-1] = unit_replacements[value[-1]]
            value = ' '.join(value[:-1]).upper() + ' [' + value[-1] + ']'
        else:
            value = ' '.join(value).upper()
        if key == 'gnss_id':
            constellation_map = {'GALILEO': 'Galileo', 'BEIDOU': 'BeiDou'}
            for old_value, new_value in constellation_map.items():
                value = value.replace(old_value, new_value)
        if key == 'signal_type':
            if value[-1] == 'I':
                value = value[:-1] + 'i'
        label += value
    return label

def _sort_gnss_ids(unsorted_gnss_ids):
    sorted_gnss_ids = []
    unsorted_gnss_ids = list(unsorted_gnss_ids)
    for gnss in GNSS_ORDER:
        if gnss in unsorted_gnss_ids:
            unsorted_gnss_ids.remove(gnss)
            sorted_gnss_ids.append(gnss)
    sorted_gnss_ids += sorted(unsorted_gnss_ids)
    return sorted_gnss_ids

def _save_figure(figures, titles=None, prefix='', fnames=None):
    if isinstance(figures, plt.Figure):
        figures = [figures]
    if isinstance(titles, str) or titles is None:
        titles = [titles]
    if isinstance(fnames, (str, pathlib.Path)) or fnames is None:
        fnames = [fnames]
    for fig_idx, figure in enumerate(figures):
        if len(fnames) == 1 and fnames[0] is None or fnames[fig_idx] is None:
            log_path = os.path.join(os.getcwd(), 'results', TIMESTAMP)
            fo.make_dir(log_path)
            title = titles[fig_idx]
            title = title.replace(' ', '_')
            title = title.replace('.', '')
            if prefix != '' and (not prefix.endswith('_')):
                prefix += '_'
            fname = os.path.join(log_path, prefix + title + '.png')
        else:
            fname = fnames[fig_idx]
        figure.savefig(fname, dpi=300.0, format='png', bbox_inches='tight')

def _parse_metric_args(navdata, *args):
    if len(args) == 1:
        x_metric = None
        y_metric = args[0]
    elif len(args) == 2:
        x_metric = args[0]
        y_metric = args[1]
    else:
        raise ValueError('Cannot plot more than one pair of x-y values')
    for metric in [x_metric, y_metric]:
        if metric is not None and navdata.is_str(metric):
            raise KeyError(metric + ' is a non-numeric row.' + 'Unable to plot with plot_metric().')
    return (x_metric, y_metric)

def _new_cmap(rgb_color):
    num_vals = 256
    vals = np.ones((num_vals, 4))
    vals[:, 0] = np.linspace(1.0, rgb_color[0], num_vals)
    vals[:, 1] = np.linspace(1.0, rgb_color[1], num_vals)
    vals[:, 2] = np.linspace(1.0, rgb_color[2], num_vals)
    cmap = ListedColormap(vals)
    return cmap

def _zoom_center(lats, lons, width_to_height=1.25):
    maxlon, minlon = (max(lons), min(lons))
    maxlat, minlat = (max(lats), min(lats))
    center = {'lon': round((maxlon + minlon) / 2, 6), 'lat': round((maxlat + minlat) / 2, 6)}
    lon_zoom_range = np.array([0.0007, 0.0014, 0.003, 0.006, 0.012, 0.024, 0.048, 0.096, 0.192, 0.3712, 0.768, 1.536, 3.072, 6.144, 11.8784, 23.7568, 47.5136, 98.304, 190.0544, 360.0])
    margin = 2.5
    height = (maxlat - minlat) * margin * width_to_height
    width = (maxlon - minlon) * margin
    lon_zoom = np.interp(width, lon_zoom_range, range(20, 0, -1))
    lat_zoom = np.interp(height, lon_zoom_range, range(20, 0, -1))
    zoom = floor(min(lon_zoom, lat_zoom))
    zoom = min(zoom, 18)
    return (zoom, center)

def _save_plotly(figures, titles=None, prefix='', fnames=None, width=730, height=520):
    if isinstance(figures, go.Figure):
        figures = [figures]
    if isinstance(titles, str) or titles is None:
        titles = [titles]
    if isinstance(fnames, (str, pathlib.Path)) or fnames is None:
        fnames = [fnames]
    for fig_idx, figure in enumerate(figures):
        if len(fnames) == 1 and fnames[0] is None or fnames[fig_idx] is None:
            log_path = os.path.join(os.getcwd(), 'results', TIMESTAMP)
            fo.make_dir(log_path)
            title = titles[fig_idx]
            title = title.replace(' ', '_')
            title = title.replace('.', '')
            if prefix != '' and (not prefix.endswith('_')):
                prefix += '_'
            fname = os.path.join(log_path, prefix + title + '.png')
        else:
            fname = fnames[fig_idx]
        while True:
            process = Process(target=_write_plotly, name='write_plotly', args=(figure, fname, width, height))
            process.start()
            process.join(180)
            if process.is_alive():
                process.terminate()
                process.join()
                continue
            break

def _write_plotly(figure, fname, width, height):
    while True:
        try:
            figure.write_image(fname, width=width, height=height)
            break
        except ValueError as error:
            figure.layout.mapbox.zoom -= 1
            if figure.layout.mapbox.zoom < 1:
                print(error)
                break

