import os
import shutil
import gzip
import ftplib
from ftplib import FTP_TLS, FTP
from datetime import datetime, timezone
import numpy as np
import pandas as pd
try:
    import unlzw3
except ModuleNotFoundError:
    unlzw3 = None
try:
    import georinex
except ModuleNotFoundError:
    georinex = None
import gnss_lib_py.utils.constants as consts
from gnss_lib_py.parsers.navdata import NavData
from gnss_lib_py.utils.time_conversions import datetime_to_gps_millis, tzinfo_to_utc

class EphemerisManager:

    def __init__(self, data_directory=os.path.join(os.getcwd(), 'data', 'ephemeris'), verbose=False):
        self.data_directory = data_directory
        nasa_dir = os.path.join(data_directory, 'nasa')
        igs_dir = os.path.join(data_directory, 'igs')
        os.makedirs(nasa_dir, exist_ok=True)
        os.makedirs(igs_dir, exist_ok=True)
        self.data = None
        self.leapseconds = None
        self.verbose = verbose

    def get_ephemeris(self, timestamp, satellites=None):
        systems = EphemerisManager.get_constellations(satellites)
        timestamp = tzinfo_to_utc(timestamp)
        if not isinstance(self.data, pd.DataFrame):
            same_day = (datetime.now(timezone.utc) - timestamp).days <= 0
            self.load_data(timestamp, systems, same_day)
        data = self.data
        if satellites is not None:
            data = data.loc[data['sv'].isin(satellites)]
        time_cropped_data = data.loc[data['time'] < timestamp]
        time_cropped_data = time_cropped_data.sort_values('time').groupby('sv').last().drop(labels='index', axis='columns')
        if satellites is not None and len(time_cropped_data) < len(satellites):
            if len(time_cropped_data) != 0:
                satellites = list(set(satellites) - set(time_cropped_data.index))
            systems = EphemerisManager.get_constellations(satellites)
            prev_day_timestamp = datetime(year=timestamp.year, month=timestamp.month, day=timestamp.day - 1, hour=23, minute=59, second=59, microsecond=999999, tzinfo=timezone.utc)
            self.load_data(prev_day_timestamp, systems, False)
            prev_data = self.data
            if satellites is not None:
                prev_data = prev_data.loc[prev_data['sv'].isin(satellites)]
            prev_data = prev_data.sort_values('time').groupby('sv').last().drop(labels='index', axis='columns')
            data = pd.concat((time_cropped_data, prev_data))
        else:
            data = time_cropped_data
        data['Leap Seconds'] = self.leapseconds
        data = data.reset_index()
        gps_millis = [datetime_to_gps_millis(df_row['time']) for _, df_row in data.iterrows()]
        data['gps_millis'] = gps_millis
        data = data.drop(columns=['time'])
        data = data.rename(columns={'sv': 'sv_id'})
        if 'GPSWeek' in data.columns:
            data = data.rename(columns={'GPSWeek': 'gps_week'})
            if 'GALWeek' in data.columns:
                data['gps_week'] = np.where(pd.isnull(data['gps_week']), data['GALWeek'], data['gps_week'])
        elif 'GALWeek' in data.columns:
            data = data.rename(columns={'GALWeek': 'gps_week'})
        if len(data) == 0:
            raise RuntimeError('No ephemeris data available for the ' + 'given satellites')
        data_navdata = NavData(pandas_df=data)
        data_navdata['gnss_sv_id'] = data_navdata['sv_id']
        gnss_chars = [sv_id[0] for sv_id in np.atleast_1d(data_navdata['sv_id'])]
        gnss_nums = [sv_id[1:] for sv_id in np.atleast_1d(data_navdata['sv_id'])]
        gnss_id = [consts.CONSTELLATION_CHARS[gnss_char] for gnss_char in gnss_chars]
        data_navdata['gnss_id'] = np.asarray(gnss_id)
        data_navdata['sv_id'] = np.asarray(gnss_nums, dtype=int)
        return data_navdata

    def load_data(self, timestamp, constellations=None, same_day=False):
        filepaths = EphemerisManager.get_filepaths(timestamp)
        data_list = []
        if constellations == None:
            for fileinfo in filepaths.values():
                data = self.get_ephemeris_dataframe(fileinfo, constellations)
                data_list.append(data)
        else:
            legacy_systems = set(['G', 'R'])
            legacy_systems_only = len(constellations - legacy_systems) == 0
            if not same_day:
                if legacy_systems_only:
                    if 'G' in constellations:
                        data_list.append(self.get_ephemeris_dataframe(filepaths['nasa_daily_gps'], constellations=None))
                    if 'R' in constellations:
                        data_list.append(self.get_ephemeris_dataframe(filepaths['nasa_daily_glonass'], constellations=None))
                else:
                    data_list.append(self.get_ephemeris_dataframe(filepaths['nasa_daily_combined'], constellations))
            elif legacy_systems_only and 'G' in constellations:
                data_list.append(self.get_ephemeris_dataframe(filepaths['nasa_daily_gps'], constellations=None))
            else:
                data_list.append(self.get_ephemeris_dataframe(filepaths['bkg_daily_combined'], constellations))
        data = pd.DataFrame()
        for new_data in data_list:
            data = pd.concat((data, new_data), ignore_index=True)
        data.reset_index(inplace=True)
        data.sort_values('time', inplace=True, ignore_index=True)
        self.data = data

    def get_ephemeris_dataframe(self, fileinfo, constellations=None):
        filepath = fileinfo['filepath']
        url = fileinfo['url']
        directory = os.path.split(filepath)[0]
        filename = os.path.split(filepath)[1]
        if url == 'igs-ftp.bkg.bund.de':
            dest_filepath = os.path.join(self.data_directory, 'igs', filename)
        else:
            dest_filepath = os.path.join(self.data_directory, 'nasa', filename)
        decompressed_filename = os.path.splitext(dest_filepath)[0]
        if not os.path.isfile(decompressed_filename):
            self.retrieve_file(url, directory, filename, dest_filepath)
        if not self.leapseconds:
            self.leapseconds = EphemerisManager.load_leapseconds(decompressed_filename)
        if georinex is None:
            raise ModuleNotFoundError('georinex is required to parse broadcast ephemeris files')
        if constellations is not None:
            data = georinex.load(decompressed_filename, use=constellations, verbose=self.verbose).to_dataframe()
        else:
            data = georinex.load(decompressed_filename, verbose=self.verbose).to_dataframe()
        data.dropna(how='all', inplace=True)
        data.reset_index(inplace=True)
        data['source'] = decompressed_filename
        data['t_oc'] = pd.to_numeric(data['time'] - datetime(1980, 1, 6, 0, 0, 0))
        data['t_oc'] = 1e-09 * data['t_oc'] - consts.WEEKSEC * np.floor(1e-09 * data['t_oc'] / consts.WEEKSEC)
        data['time'] = data['time'].dt.tz_localize('UTC')
        data.rename(columns={'M0': 'M_0', 'Eccentricity': 'e', 'Toe': 't_oe', 'DeltaN': 'deltaN', 'Cuc': 'C_uc', 'Cus': 'C_us', 'Cic': 'C_ic', 'Crc': 'C_rc', 'Cis': 'C_is', 'Crs': 'C_rs', 'Io': 'i_0', 'Omega0': 'Omega_0'}, inplace=True)
        return data

    @staticmethod
    def get_filetype(timestamp):
        if timestamp >= datetime(2020, 12, 1, 0, 0, 0, tzinfo=timezone.utc):
            extension = '.gz'
        else:
            extension = '.Z'
        return extension

    @staticmethod
    def load_leapseconds(filename):
        with open(filename) as f:
            for line in f:
                if 'LEAP SECONDS' in line:
                    read_lp_sec = int(line.split()[0])
                    return read_lp_sec
                if 'END OF HEADER' in line:
                    return None
        return None

    @staticmethod
    def get_constellations(satellites):
        if isinstance(satellites, list):
            systems = set()
            for sat in satellites:
                systems.add(sat[0])
            return systems
        return None

    def retrieve_file(self, url, directory, filename, dest_filepath):
        secure = bool(url == 'gdc.cddis.eosdis.nasa.gov')
        if self.verbose:
            print('Retrieving ' + directory + '/' + filename + ' from ' + url)
        ftp = self.connect(url, secure)
        src_filepath = directory + '/' + filename
        try:
            with open(dest_filepath, 'wb') as handle:
                ftp.retrbinary('RETR ' + src_filepath, handle.write)
        except ftplib.error_perm as err:
            os.remove(dest_filepath)
            raise ftplib.error_perm(str(err) + ' Failed to retrieve ' + src_filepath + ' from ' + url)
        ftp.quit()
        if ftp is not None:
            ftp.close()
        self.decompress_file(dest_filepath)

    def decompress_file(self, filepath):
        extension = os.path.splitext(filepath)[1]
        decompressed_path = os.path.splitext(filepath)[0]
        if extension == '.gz':
            with gzip.open(filepath, 'rb') as f_in:
                with open(decompressed_path, 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)
        elif extension == '.Z':
            if unlzw3 is None:
                raise ModuleNotFoundError('unlzw3 is required to decompress .Z ephemeris files')
            with open(filepath, 'rb') as f_in:
                with open(decompressed_path, 'wb') as f_out:
                    f_out.write(unlzw3.unlzw(f_in.read()))
        os.remove(filepath)

    def connect(self, url, secure):
        if secure:
            ftp = FTP_TLS(url)
            ftp.login()
            ftp.prot_p()
        else:
            ftp = FTP(url)
            ftp.login()
        return ftp

    @staticmethod
    def get_filepaths(timestamp):
        timetuple = timestamp.timetuple()
        extension = EphemerisManager.get_filetype(timestamp)
        filepaths = {}
        directory = 'gnss/data/daily/' + str(timetuple.tm_year) + '/brdc/'
        filename = 'BRDC00IGS_R_' + str(timetuple.tm_year) + str(timetuple.tm_yday).zfill(3) + '0000_01D_MN.rnx.gz'
        filepaths['nasa_daily_combined'] = {'filepath': directory + filename, 'url': 'gdc.cddis.eosdis.nasa.gov'}
        filename = 'brdc' + str(timetuple.tm_yday).zfill(3) + '0.' + str(timetuple.tm_year)[-2:] + 'n' + extension
        filepaths['nasa_daily_gps'] = {'filepath': directory + filename, 'url': 'gdc.cddis.eosdis.nasa.gov'}
        filename = 'brdc' + str(timetuple.tm_yday).zfill(3) + '0.' + str(timetuple.tm_year)[-2:] + 'g' + extension
        filepaths['nasa_daily_glonass'] = {'filepath': directory + filename, 'url': 'gdc.cddis.eosdis.nasa.gov'}
        directory = '/IGS/BRDC/' + str(timetuple.tm_year) + '/' + str(timetuple.tm_yday).zfill(3) + '/'
        filename = 'BRDC00WRD_S_' + str(timetuple.tm_year) + str(timetuple.tm_yday).zfill(3) + '0000_01D_MN.rnx.gz'
        filepaths['bkg_daily_combined'] = {'filepath': directory + filename, 'url': 'igs-ftp.bkg.bund.de'}
        return filepaths

