__authors__ = 'Sriramya Bhamidipati'
__date__ = '09 June 2022'
import os
import warnings
from datetime import datetime, timedelta, timezone
import numpy as np
from scipy import interpolate
from gnss_lib_py.parsers.ephemeris import EphemerisManager
from gnss_lib_py.parsers.navdata import NavData
from gnss_lib_py.utils.sim_gnss import find_sat
from gnss_lib_py.utils.time_conversions import gps_millis_to_tow
from gnss_lib_py.utils.time_conversions import datetime_to_gps_millis
import gnss_lib_py.utils.constants as consts
NUMSATS = {'gps': (32, 'G'), 'galileo': (36, 'E'), 'beidou': (46, 'C'), 'glonass': (26, 'R'), 'qzss': (3, 'J')}

class Sp3:

    def __init__(self):
        self.const = None
        self.xpos = []
        self.ypos = []
        self.zpos = []
        self.tym = []
        self.utc_time = []

    def __eq__(self, other):
        bool_check = (self.const == other.const) & (self.xpos == other.xpos) & (self.ypos == other.ypos) & (self.zpos == other.zpos) & (self.tym == other.tym) & (self.utc_time == other.utc_time)
        return bool_check

def parse_sp3(input_path, constellation='gps'):
    if not isinstance(input_path, (str, os.PathLike)):
        raise TypeError('input_path must be string or path-like')
    if not os.path.exists(input_path):
        raise FileNotFoundError('file not found')
    with open(input_path, 'r', encoding='utf-8') as infile:
        data = [line.strip() for line in infile]
    if constellation in NUMSATS.keys():
        nsvs = NUMSATS[constellation][0]
    else:
        raise RuntimeError('No support exists for specified constellation')
    sp3data = []
    for _ in np.arange(0, nsvs + 1):
        sp3data.append(Sp3())
        sp3data[-1].const = constellation
    for dval in data:
        if len(dval) == 0:
            continue
        if dval[0] == '*':
            temp = dval.split()
            curr_time = datetime(int(temp[1]), int(temp[2]), int(temp[3]), int(temp[4]), int(temp[5]), int(float(temp[6])), tzinfo=timezone.utc)
            gps_millis = datetime_to_gps_millis(curr_time, add_leap_secs=False)
        if 'P' in dval[0]:
            temp = dval.split()
            if temp[0][1] == NUMSATS[constellation][1]:
                prn = int(temp[0][2:])
                sp3data[prn].utc_time.append(curr_time)
                sp3data[prn].tym.append(gps_millis)
                sp3data[prn].xpos.append(float(temp[1]) * 1000.0)
                sp3data[prn].ypos.append(float(temp[2]) * 1000.0)
                sp3data[prn].zpos.append(float(temp[3]) * 1000.0)
    no_data_arrays = []
    for prn in np.arange(1, nsvs + 1):
        if len(sp3data[prn].tym) == 0:
            no_data_arrays.append(prn)
    if len(no_data_arrays) == nsvs:
        warnings.warn('No sp3 data found for PRNs: ' + str(no_data_arrays), RuntimeWarning)
    return sp3data

class Clk:

    def __init__(self):
        self.const = None
        self.clk_bias = []
        self.utc_time = []
        self.tym = []

    def __eq__(self, other):
        return (self.const == other.const) & (self.clk_bias == other.clk_bias) & (self.tym == other.tym) & (self.utc_time == other.utc_time)

def parse_clockfile(input_path, constellation='gps'):
    if not isinstance(input_path, (str, os.PathLike)):
        raise TypeError('input_path must be string or path-like')
    if not os.path.exists(input_path):
        raise FileNotFoundError('file not found')
    if constellation in NUMSATS.keys():
        nsvs = NUMSATS[constellation][0]
    else:
        raise RuntimeError('No support exists for specified constellation')
    clkdata = []
    for _ in np.arange(0, nsvs + 1):
        clkdata.append(Clk())
        clkdata[-1].const = constellation
    with open(input_path, 'r', encoding='utf-8') as infile:
        clk = infile.readlines()
    line = 0
    while True:
        if 'OF SOLN SATS' not in clk[line]:
            del clk[line]
        else:
            line += 1
            break
    line = 0
    while True:
        if 'END OF HEADER' not in clk[line]:
            line += 1
        else:
            del clk[0:line + 1]
            break
    timelist = []
    for _, clk_val in enumerate(clk):
        if clk_val[0:2] == 'AS':
            timelist.append(clk_val.split())
    for _, timelist_val in enumerate(timelist):
        dval = timelist_val[1]
        if dval[0] == NUMSATS[constellation][1]:
            prn = int(dval[1:])
            curr_time = datetime(year=int(timelist_val[2]), month=int(timelist_val[3]), day=int(timelist_val[4]), hour=int(timelist_val[5]), minute=int(timelist_val[6]), second=int(float(timelist_val[7])), tzinfo=timezone.utc)
            clkdata[prn].utc_time.append(curr_time)
            gps_millis = datetime_to_gps_millis(curr_time, add_leap_secs=False)
            clkdata[prn].tym.append(gps_millis)
            clkdata[prn].clk_bias.append(float(timelist_val[9]))
    infile.close()
    no_data_arrays = []
    for prn in np.arange(1, nsvs + 1):
        if len(clkdata[prn].tym) == 0:
            no_data_arrays.append(prn)
    if len(no_data_arrays) == nsvs:
        warnings.warn('No clk data found for PRNs: ' + str(no_data_arrays), RuntimeWarning)
    return clkdata

def extract_sp3(sp3data, sidx, ipos=10, method='CubicSpline', verbose=False):
    func_satpos = np.empty((3,), dtype=object)
    func_satpos[:] = np.nan
    if method == 'CubicSpline':
        low_i = sidx - ipos if sidx - ipos >= 0 else 0
        high_i = sidx + ipos if sidx + ipos <= len(sp3data.tym) else -1
        if verbose:
            print('Nearest sp3: ', sidx, sp3data.tym[sidx], sp3data.xpos[sidx], sp3data.ypos[sidx], sp3data.zpos[sidx])
        func_satpos[0] = interpolate.CubicSpline(sp3data.tym[low_i:high_i], sp3data.xpos[low_i:high_i])
        func_satpos[1] = interpolate.CubicSpline(sp3data.tym[low_i:high_i], sp3data.ypos[low_i:high_i])
        func_satpos[2] = interpolate.CubicSpline(sp3data.tym[low_i:high_i], sp3data.zpos[low_i:high_i])
    return func_satpos

def extract_clk(clkdata, sidx, ipos=10, method='CubicSpline', verbose=False):
    if method == 'CubicSpline':
        low_i = sidx - ipos if sidx - ipos >= 0 else 0
        high_i = sidx + ipos if sidx + ipos <= len(clkdata.tym) else -1
        if verbose:
            print('Nearest clk: ', sidx, clkdata.tym[sidx], clkdata.clk_bias[sidx])
        func_satbias = interpolate.CubicSpline(clkdata.tym[low_i:high_i], clkdata.clk_bias[low_i:high_i])
    return func_satbias

def sp3_snapshot(func_satpos, cxtime, hstep=0.5, method='CubicSpline'):
    if method == 'CubicSpline':
        sat_x = func_satpos[0]([cxtime - 0.5 * hstep, cxtime, cxtime + 0.5 * hstep])
        sat_y = func_satpos[1]([cxtime - 0.5 * hstep, cxtime, cxtime + 0.5 * hstep])
        sat_z = func_satpos[2]([cxtime - 0.5 * hstep, cxtime, cxtime + 0.5 * hstep])
    satpos_sp3 = np.array([sat_x[1], sat_y[1], sat_z[1]])
    satvel_sp3 = np.array([(sat_x[2] - sat_x[0]) / hstep, (sat_y[2] - sat_y[0]) / hstep, (sat_z[2] - sat_z[0]) / hstep])
    return (satpos_sp3, satvel_sp3 * 1000.0)

def clk_snapshot(func_satbias, cxtime, hstep=0.5, method='CubicSpline'):
    if method == 'CubicSpline':
        sat_t = func_satbias([cxtime - 0.5 * hstep, cxtime, cxtime + 0.5 * hstep])
    satbias_clk = sat_t[1]
    satdrift_clk = (sat_t[2] - sat_t[0]) / hstep
    return (satbias_clk, satdrift_clk * 1000.0)

def multi_gnss_from_precise_eph(navdata, sp3_path, clk_path, constellations, verbose=False):
    navdata_prcs_merged = NavData()
    for sv in constellations:
        navdata_prcs_gnss = navdata.where('gnss_id', sv)
        sp3_parsed_gnss = parse_sp3(sp3_path, constellation=sv)
        clk_parsed_gnss = parse_clockfile(clk_path, constellation=sv)
        derived_prcs_gnss = single_gnss_from_precise_eph(navdata_prcs_gnss, sp3_parsed_gnss, clk_parsed_gnss, verbose=verbose)
        navdata_prcs_merged.concat(navdata_prcs_gnss, inplace=True)
    return navdata_prcs_merged

